document.addEventListener('click',event=>{const button=event.target.closest?.('[data-restore-draft]'),form=button?.closest?.('form');if(form?.id!=='secretary-draft-form')return;for(const name of ['verify_public','verify_entity']){const field=$(`[name="${name}"]`,form);if(field)field.checked=false;}saveDraft(form);secretarySyncForm(form);});
document.addEventListener('input',event=>{const form=event.target.closest?.('form');if(['secretary-draft-form','secretary-progress-form'].includes(form?.id)){secretaryPlanChanged(form,event.target);saveDraft(form);secretarySyncForm(form);}});
document.addEventListener('change',event=>{const form=event.target.closest?.('form');if(form?.id==='secretary-progress-form'){secretaryPlanChanged(form,event.target);saveDraft(form);}if(form?.id==='secretary-draft-form'){saveDraft(form);secretarySyncForm(form);}if(event.target.hasAttribute?.('data-secretary-run')){const context=state.detail?.data?.secretary;if(!secretaryCurrent(context))return;const current=secretaryVisibleForms(context);if(current.some(form=>dirtyForm(form)||form.dataset.pendingDraft)){event.target.value=String(context.run?.id||'');secretaryMessage(context,'先保存当前准备稿，再切换任务。');return;}if(event.target.value)secretaryLoad(context,{runId:event.target.value});}});
